String nome = JOptionPane.showInputDialog(this, "Digite o nome:");
if (nome != null && !nome.trim().isEmpty()) {
    System.out.println(nome.trim());
}

int resposta = JOptionPane.showConfirmDialog(this, "Limpar dados?", "Confirmação", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE);
if (resposta == JOptionPane.YES_OPTION) {
    jTextField1.setText("");
}

if (resposta == JOptionPane.CLOSED_OPTION) {
    // A janela foi fechada.
}

String nome = jTextField1.getText().trim();
if (nome.isEmpty() || jComboBox1.getSelectedIndex() <= 0) {
    JOptionPane.showMessageDialog(this, "Informe nome e curso", "Atenção", JOptionPane.WARNING_MESSAGE);
} else {
    String curso = jComboBox1.getSelectedItem().toString();
    JOptionPane.showMessageDialog(this, "Aluno: " + nome + "\nCurso: " + curso, "Cadastro", JOptionPane.INFORMATION_MESSAGE);
}

int resposta = JOptionPane.showConfirmDialog(this, "Deseja limpar os dados?", "Confirmação", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE);
if (resposta == JOptionPane.YES_OPTION) {
    jTextField1.setText("");
    jComboBox1.setSelectedIndex(0);
    jTextField1.requestFocusInWindow();
}
